import subprocess, sys
sys.path.insert(0, '.')
from samtools import parse_flags_arg, format_flags_value

def orig(t):
    p=subprocess.run(["./executable","flags",t], capture_output=True, text=True)
    return p.stdout, p.returncode

def mine(t):
    ok,val=parse_flags_arg(t)
    if ok:
        return format_flags_value(val), 0
    else:
        return "", 1

tests = ["", " ", "  ", ",", ",,", "PAIRED,", ",PAIRED", "PAIRED,,UNMAP", "0,", ",0", "0x", "0X", "x", "X", "0x10 ", " 0x10", "\t10", "10\t", "0_10", "1_0", "PaIrEd", "proper_pair", "PROPER-PAIR", "PROPER PAIR", "DUP,SUPPLEMENTARY", "DUP, SUPPLEMENTARY", "4294967295", "4294967296", "4294967297", "2147483647", "2147483648", "18446744073709551615", "18446744073709551616", "0xffffffff", "0x1ffffffff", "0777", "08", "09", "00", "000", "-0", "+0", "  +10  ", "--10", "++10", "1abc", "0xyz", "a1", "PAIRED,PAIRED", "0x10,0x20", "-0x10", "+", "+10", "9223372036854775807", "9223372036854775808", "-9223372036854775808", "-9223372036854775809", "99999999999999999999999", "-99999999999999999999999", "UNMAP,PAIRED", "0x1001", "4097"]
mismatch=0
for t in tests:
    o_out,o_rc=orig(t)
