# BAM tag handling
def parse_tag_value(typ, val_str):
    # For encoding SAM tag to BAM bytes: return BAM type char and bytes
    # typ is SAM type (A,i,f,Z,H,B), val_str is string after "TAG:TYPE:"
    # Returns (bam_type_byte, bytes)
    if typ == 'A':
        # char
        return (b'A', val_str.encode()[:1] if val_str else b'\x00')
    elif typ == 'i' or typ == 'I':
        # integer: choose smallest representation? For simplicity, use 'i' (int32) if fits, else? Actually BAM uses 'c','C','s','S','i','I'? But SAM type 'i' can be stored as any of those in BAM, with type byte indicating storage.
        # To match original's smallest encoding, implement smallest: try c,C,s,S,i
        try:
            v = int(val_str)
        except:
            v = 0
        # Determine smallest
        if -128 <= v <= 127:
            return (b'c', struct.pack('<b', v))
        elif 0 <= v <= 255:
            return (b'C', struct.pack('<B', v))
        elif -32768 <= v <= 32767:
            return (b's', struct.pack('<h', v))
        elif 0 <= v <= 65535:
            return (b'S', struct.pack('<H', v))
        elif -2147483648 <= v <= 2147483647:
            return (b'i', struct.pack('<i', v))
        elif 0 <= v <= 4294967295:
            return (b'I', struct.pack('<I', v))
        else:
            # overflow? Use i with truncation? Original would error? For now, use i with low 32?
            return (b'i', struct.pack('<i', v & 0xFFFFFFFF if v>=0 else ((v+2**32)&0xFFFFFFFF)-2**32 if False else 0))
    elif typ == 'f':
        try:
            v = float(val_str)
        except:
            v = 0.0
        return (b'f', struct.pack('<f', v))
    elif typ == 'Z' or typ == 'H':
        # string with null terminator, type Z or H? In BAM, Z and H are stored as Z/H with null?
        # Actually BAM stores Z as 'Z', H as 'H'? Yes.
        return (typ.encode(), val_str.encode() + b'\x00')
    elif typ == 'B':
        # Array: val_str is like "S,12561,2,20,112" -> subtype S, values
        parts = val_str.split(',')
        if not parts:
            return (b'B', b'')
        subtype = parts[0]
        vals = parts[1:]
        # subtype can be c,C,s,S,i,I,f
        # Encode: subtype byte, len (int32), then values
        out = bytearray()
        out += subtype.encode()
        out += struct.pack('<i', len(vals))
        for v in vals:
            if subtype == 'c':
                out += struct.pack('<b', int(v))
            elif subtype == 'C':
                out += struct.pack('<B', int(v))
            elif subtype == 's':
                out += struct.pack('<h', int(v))
            elif subtype == 'S':
                out += struct.pack('<H', int(v))
            elif subtype == 'i':
                out += struct.pack('<i', int(v))
            elif subtype == 'I':
                out += struct.pack('<I', int(v))
            elif subtype == 'f':
                out += struct.pack('<f', float(v))
            else:
                # unknown? treat as i?
                out += struct.pack('<i', int(v))
        return (b'B', bytes(out))
    else:
        # unknown type? Store as Z?
        return (typ.encode() if len(typ)==1 else b'Z', val_str.encode() + b'\x00')

def encode_tags_to_bam(tags_list):
    # tags_list: list of strings "TAG:TYPE:VALUE"
    out = bytearray()
    for t in tags_list:
        if len(t) < 5 or t[2] != ':' or t[4] != ':':
            continue
        tag = t[0:2]
        typ = t[3]
        val = t[5:]
        btype, bval = parse_tag_value(typ, val)
        out += tag.encode() + btype + bval
    return bytes(out)

def decode_bam_tags(data):
    # data: bytes of tags area, returns list of strings "TAG:TYPE:VALUE"
    tags = []
    i = 0
    n = len(data)
    while i+3 <= n:
        tag = data[i:i+2].decode(errors='ignore')
        typ = chr(data[i+2])
        i += 3
        if typ == 'A':
            if i >= n:
                break
            val = chr(data[i])
            i += 1
            tags.append(f"{tag}:A:{val}")
        elif typ == 'c':
            if i+1 > n: break
            v = struct.unpack('<b', data[i:i+1])[0]
            i += 1
            tags.append(f"{tag}:i:{v}")
        elif typ == 'C':
            if i+1 > n: break
            v = struct.unpack('<B', data[i:i+1])[0]
            i += 1
            tags.append(f"{tag}:i:{v}")
        elif typ == 's':
            if i+2 > n: break
            v = struct.unpack('<h', data[i:i+2])[0]
            i += 2
            tags.append(f"{tag}:i:{v}")
        elif typ == 'S':
            if i+2 > n: break
            v = struct.unpack('<H', data[i:i+2])[0]
            i += 2
            tags.append(f"{tag}:i:{v}")
        elif typ == 'i':
            if i+4 > n: break
            v = struct.unpack('<i', data[i:i+4])[0]
            i += 4
            tags.append(f"{tag}:i:{v}")
